import { Sidebar, SidebarHeader } from "@/components/ui/sidebar"

import { AnimatedSidebarTrigger } from "@/components/blocks/sidebar-playground/animated-sidebar-trigger"
import { usePlayground } from "@/components/blocks/sidebar-playground/playground-config"

export function AppSidebar() {
  const { state } = usePlayground()
  const { variant, collapsible } = state

  return (
    <Sidebar side="left" variant={variant} collapsible={collapsible}>
      <SidebarHeader className="h-14 shrink-0 flex-row items-center justify-end gap-0 p-0 px-4">
        <AnimatedSidebarTrigger data-testid="sidebar-trigger" />
      </SidebarHeader>
    </Sidebar>
  )
}

import { SidebarTrigger } from "@/components/ui/sidebar"
import { motion, useReducedMotion } from "motion/react"
import type { ComponentProps } from "react"

export const PLAYGROUND_SIDEBAR_TRIGGER_LAYOUT_ID = "playground-sidebar-trigger"

const sharedLayoutTransition = {
  type: "tween" as const,
  duration: 0.2,
  ease: [0.23, 1, 0.32, 1] as [number, number, number, number],
}

type AnimatedSidebarTriggerProps = ComponentProps<typeof SidebarTrigger>

export function AnimatedSidebarTrigger(props: AnimatedSidebarTriggerProps) {
  const reduceMotion = useReducedMotion()

  return (
    <motion.div
      layoutId={PLAYGROUND_SIDEBAR_TRIGGER_LAYOUT_ID}
      layout={!reduceMotion}
      transition={reduceMotion ? { duration: 0 } : sharedLayoutTransition}
      className="shrink-0"
    >
      <SidebarTrigger {...props} />
    </motion.div>
  )
}

import * as React from "react"

export type PlaygroundVariant = "sidebar" | "floating" | "inset" | "peek"
export type PlaygroundCollapsible = "offcanvas" | "icon" | "none"

export const playgroundVariants: PlaygroundVariant[] = [
  "sidebar",
  "floating",
  "inset",
  "peek",
]

export const playgroundCollapsibles: PlaygroundCollapsible[] = [
  "offcanvas",
  "icon",
  "none",
]

type PlaygroundState = {
  variant: PlaygroundVariant
  collapsible: PlaygroundCollapsible
}

type PlaygroundActions = {
  setVariant: (variant: PlaygroundVariant) => void
  setCollapsible: (collapsible: PlaygroundCollapsible) => void
}

type PlaygroundMeta = {
  providerKey: string
}

type PlaygroundContextValue = {
  state: PlaygroundState
  actions: PlaygroundActions
  meta: PlaygroundMeta
}

const PlaygroundContext = React.createContext<PlaygroundContextValue | null>(
  null,
)

export function usePlayground() {
  const context = React.useContext(PlaygroundContext)
  if (!context) {
    throw new Error("usePlayground must be used within Playground.Provider.")
  }
  return context
}

type PlaygroundProviderProps = {
  children: React.ReactNode
  defaultVariant?: PlaygroundVariant
  defaultCollapsible?: PlaygroundCollapsible
}

export function PlaygroundProvider({
  children,
  defaultVariant = "peek",
  defaultCollapsible = "offcanvas",
}: PlaygroundProviderProps) {
  const [variant, setVariant] =
    React.useState<PlaygroundVariant>(defaultVariant)
  const [collapsible, setCollapsible] =
    React.useState<PlaygroundCollapsible>(defaultCollapsible)

  const providerKey = React.useMemo(
    () => `${variant}-${collapsible}`,
    [variant, collapsible],
  )

  const value = React.useMemo<PlaygroundContextValue>(
    () => ({
      state: { variant, collapsible },
      actions: { setVariant, setCollapsible },
      meta: { providerKey },
    }),
    [variant, collapsible, providerKey],
  )

  return (
    <PlaygroundContext.Provider value={value}>
      {children}
    </PlaygroundContext.Provider>
  )
}

import { useSidebar } from "@/components/ui/sidebar"

import { AnimatedSidebarTrigger } from "@/components/blocks/sidebar-playground/animated-sidebar-trigger"

import { usePlayground } from "./playground-config"

export function PlaygroundHeader() {
  const { state } = usePlayground()
  const { state: sidebarState, peekOpen } = useSidebar()
  const showPageTrigger =
    sidebarState === "collapsed" &&
    !(state.variant === "peek" && peekOpen)

  return (
    <header className="relative flex h-14 shrink-0 items-center justify-start px-4">
      {showPageTrigger ? (
        <AnimatedSidebarTrigger
          data-slot="page-sidebar-trigger"
          data-testid="sidebar-trigger"
        />
      ) : null}
    </header>
  )
}

import { ControlGroup } from "./control-group"
import {
  playgroundCollapsibles,
  playgroundVariants,
  usePlayground,
} from "./playground-config"

export function PlaygroundControls() {
  const { state, actions } = usePlayground()
  const { variant, collapsible } = state
  const { setVariant, setCollapsible } = actions

  return (
    <>
      <section className="space-y-2">
        <h2 className="text-lg font-semibold tracking-tight">Controls</h2>
        <p className="text-sm text-muted-foreground">
          Tweak the sidebar props below. The provider remounts so each
          combination applies cleanly.
        </p>
      </section>

      <div
        className={`grid gap-6 rounded-xl border bg-card p-4 text-card-foreground shadow-sm ${
          variant === "peek" ? "sm:grid-cols-1" : "sm:grid-cols-2"
        }`}
      >
        <ControlGroup
          label="Variant"
          testId="control-variant"
          value={variant}
          options={playgroundVariants}
          onChange={setVariant}
        />
        {variant !== "peek" ? (
          <ControlGroup
            label="Collapsible"
            testId="control-collapsible"
            value={collapsible}
            options={playgroundCollapsibles}
            onChange={setCollapsible}
          />
        ) : null}
      </div>
    </>
  )
}

import { usePlayground } from "./playground-config"

export function PlaygroundActiveConfig() {
  const { state } = usePlayground()
  const { variant, collapsible } = state

  return (
    <section
      className="rounded-xl border border-dashed p-4 text-sm text-muted-foreground"
      data-testid="active-config"
    >
      Active:{" "}
      <code className="rounded bg-muted px-1.5 py-0.5 text-foreground">
        variant={variant}
      </code>{" "}
      {variant !== "peek" ? (
        <code className="rounded bg-muted px-1.5 py-0.5 text-foreground">
          collapsible={collapsible}
        </code>
      ) : null}
    </section>
  )
}

import type { ReactNode } from "react"

export function PlaygroundBody({ children }: { children: ReactNode }) {
  return (
    <div className="flex flex-1 flex-col gap-6 p-6">{children}</div>
  )
}

import type { ReactNode } from "react"

import { SidebarInset } from "@/components/ui/sidebar"

export function PlaygroundMainInset({ children }: { children: ReactNode }) {
  return (
    <SidebarInset data-testid="sidebar-inset">
      <div className="relative flex w-full flex-1 flex-col bg-background">
        {children}
      </div>
    </SidebarInset>
  )
}

import type { ReactNode } from "react"

export function PlaygroundMainStandard({ children }: { children: ReactNode }) {
  return (
    <main
      className="relative flex w-full flex-1 flex-col bg-background"
      data-testid="sidebar-main"
    >
      {children}
    </main>
  )
}

import { Button } from "@/components/ui/button"

type ControlGroupProps<T extends string> = {
  label: string
  testId: string
  value: T
  options: readonly T[]
  onChange: (next: T) => void
}

export function ControlGroup<T extends string>({
  label,
  testId,
  value,
  options,
  onChange,
}: ControlGroupProps<T>) {
  return (
    <fieldset className="space-y-2" data-testid={testId}>
      <legend className="text-sm font-medium text-foreground">{label}</legend>
      <div className="flex flex-wrap gap-2">
        {options.map((option) => (
          <Button
            key={option}
            type="button"
            size="sm"
            variant={value === option ? "default" : "outline"}
            data-testid={`${testId}-${option}`}
            aria-pressed={value === option}
            onClick={() => onChange(option)}
          >
            {option}
          </Button>
        ))}
      </div>
    </fieldset>
  )
}

/* Peek variant: app header triggers replace the built-in expand control */
[data-slot="sidebar"][data-variant="peek"] [data-slot="sidebar-expand"] {
  display: none;
}

/* Hide the page trigger as soon as peek opens */
[data-slot="sidebar-wrapper"]:has([data-slot="sidebar"][data-peek="true"])
  [data-slot="page-sidebar-trigger"] {
  display: none;
}

/* Match sidebar surface to main content (playground demo) */
[data-slot="sidebar-inner"],
[data-slot="sidebar"][data-mobile="true"] {
  background-color: var(--background);
  color: var(--foreground);
}
